    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">25<sup>431</sup> = 5<sup>862</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>862</sup> + n × 5<sup>861</sup> = 5<sup>861</sup>(5 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">275 = 25 × 11</span>"},{"quoi":"العامل 25 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>861</sup> = 5<sup>2</sup> × 5<sup>859</sup></span>"},{"quoi":"يبقى الشرط على 11","math":"بما أنّ 11 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 11"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 = 5</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 11"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 6 ؛ 17 ؛ 28</span>"}],
